document.addEventListener('change',async e=>{
  const box=e.target.closest('.indicator-check');if(!box)return;
  const wrap=box.closest('.indicator-checks');const all=[...wrap.querySelectorAll('.indicator-check')];
  const done=all.filter(x=>x.checked).length;const key=Number(wrap.dataset.key||0);const keyDone=!key||!all[key-1]||all[key-1].checked;
  wrap.querySelector('.indicator-hint').innerHTML=hintText(done,all.length,key,keyDone);
  if(state.demo)return;
  const {record,subject}=wrap.dataset;const index=Number(box.dataset.index);const checked=box.checked;
  try{
    await result(db.rpc('set_indicator_check',{p_id:record,p_subject:subject,p_index:index,p_checked:checked,p_text:box.dataset.text||''}));
    const rest=state.indicatorChecks.filter(c=>!(c.session_student_id===record&&c.subject===subject&&c.indicator_index===index));
    state.indicatorChecks=checked?[...rest,{session_student_id:record,subject,indicator_index:index,level_snapshot:0,indicator_text:box.dataset.text||''}]:rest;
  }catch(error){
    // The tick is the teacher's record of what they saw; if it did not save, say so rather than let it look saved.
    box.checked=!checked;
    const back=all.filter(x=>x.checked).length;
    wrap.querySelector('.indicator-hint').innerHTML=hintText(back,all.length,key,!key||!all[key-1]||all[key-1].checked);
    notify(error.message||'Centang gagal disimpan.',true);
  }
});

document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action],[data-view]');if(!b)return;e.preventDefault();
  if(b.dataset.view){state.view=b.dataset.view;state.active=null;render();return;}
  const {action,id,kind}=b.dataset;
  try{
    if(action==='demo')return demo();
    if(action==='curriculum-tab'){state.curriculumTab=id;return render();}
    if(action==='curriculum-subject'){state.curriculumSubject=id;return render();}
    if(action==='curriculum-phase'){state.curriculumPhase=id;return render();}
    if(action==='refresh'){await refresh();return notify('Data terbaru sudah dimuat.');}
    if(action==='logout'){if(db&&!state.demo)await db.auth.signOut();resetSession();return login();}
    if(action==='close')return document.querySelector('#modal').close();
    if(action==='student')return studentForm(state.students.find(s=>s.id===id));
    if(action==='new-student'){if(state.role!=='teacher')return notify('Siswa baru ditambahkan oleh guru.',true);return studentForm();}
    if(action==='new-session')return newSession();
    if(action==='new-schedule')return scheduleForm();
    if(action==='edit-schedule')return scheduleForm(state.schedules.find(x=>x.id===id));
    if(action==='open-session'){state.active=id;return render();}
    if(action==='back-sessions'){state.active=null;return render();}
    if(action==='password')return modal('Ganti kata sandi',`<form data-form="password"><p class="muted">Kata sandi baru minimal 8 karakter. Setelah diganti, sesi di perangkat lain tetap berjalan sampai Anda keluar dari sana.</p>${field('Kata sandi baru','password','password','','required minlength="8" autocomplete="new-password"')}${field('Ulangi kata sandi baru','confirm','password','','required minlength="8" autocomplete="new-password"')}<button class="primary full">Simpan kata sandi baru</button></form>`);
    if(action==='new-member')return modal('Daftarkan guru',`<form data-form="member">${field('Nama guru','name','text','','required maxlength="120"')}${field('Email guru','email','email','','required')}<button class="primary full">Daftarkan email guru</button></form>`);
    if(action==='edit-curriculum'){const c=state.curriculum.find(c=>c.level===Number(id));return modal(`Kurikulum level ${id}`,`<form data-form="curriculum" data-id="${id}">${subjects.map(k=>`<fieldset class="curriculum-edit"><h3>${h(subjectLabels[k])}</h3>${area('Tujuan kompetensi',k,c[k],'required maxlength="2000"')}${area('Indikator (satu per baris, maksimal 6)',`${k}_indicators`,indicatorsOf(c,k).join('\n'),'maxlength="3000"')}${field('Nomor indikator simpul spiral (0 bila tidak ada)',`${k}_key`,'number',String(Number(c[`${k}_key`]||0)),'min="0" max="6"')}${area('Simpul spiral menuju level berikutnya',`${k}_spiral`,c[`${k}_spiral`]||'','maxlength="2000"')}${area('Bukti keberhasilan',`${k}_criteria`,c[`${k}_criteria`],'required maxlength="2000"')}</fieldset>`).join('')}<button class="primary">Simpan kurikulum</button></form>`);}
    if(action==='copy'){await navigator.clipboard.writeText(state.records.find(r=>r.id===id).report);return notify('Pesan berhasil disalin.');}
    if(action==='print'){document.querySelectorAll('.session-card').forEach(el=>el.classList.toggle('print-target',!!el.querySelector(`[data-id="${id}"]`)));return window.print();}
    guardDemo();b.disabled=true;
    if(action==='delete-student'){const s=state.students.find(x=>x.id===id);if(!confirm(`Hapus ${s?.name||'siswa ini'} secara permanen? Data yang sudah dihapus tidak bisa dikembalikan.`))return;await result(db.rpc('delete_student',{p_student:id}));document.querySelector('#modal').close();await refresh();return notify('Siswa dihapus.');}
    if(action==='toggle-student'){const s=state.students.find(x=>x.id===id);const activate=b.dataset.active==='true';if(!confirm(activate?`Aktifkan kembali ${s?.name||'siswa ini'}?`:`Nonaktifkan ${s?.name||'siswa ini'}? Anak tidak ikut sesi kelas, tetapi riwayat belajarnya tetap tersimpan.`))return;await result(db.rpc('set_student_active',{p_student:id,p_active:activate}));document.querySelector('#modal').close();await refresh();return notify(activate?'Siswa diaktifkan kembali.':'Siswa dinonaktifkan.');}
    if(action==='delete-schedule'){if(!confirm('Hapus sesi jadwal ini? Data siswa tidak ikut terhapus.'))return;await result(db.from('schedules').delete().eq('id',id));document.querySelector('#modal').close();await refresh();return notify('Sesi jadwal dihapus.');}
    if(action==='generate-class'){
      const c=state.classes.find(c=>c.id===id);if(c?.material)return notify('Panduan kelas tersimpan sudah tampil.');
      b.textContent='Sedang menyusun…';const {data,error}=await db.functions.invoke('generate-learning',{body:{session_id:id,kind:'class_material'}});
      if(error){let detail;try{detail=await error.context?.json();}catch{}throw new Error(detail?.error||error.message);}if(data?.error)throw new Error(data.error);
      await refresh();return notify('Panduan kelas tersimpan. Periksa sebelum digunakan.');
    }
    if(action==='print-class'){document.querySelector('.class-guide')?.classList.add('print-target');return window.print();}
    if(action==='register'){const form=document.querySelector('#login-form');if(!form.reportValidity())return;const f=new FormData(form);await result(db.auth.signUp({email:f.get('email'),password:f.get('password'),options:{emailRedirectTo:location.origin+location.pathname}}));notify('Aktivasi diterima. Periksa email konfirmasi, lalu masuk.');}
    if(action==='toggle-member'){const m=state.members.find(m=>m.email===id);await result(db.from('access_list').update({active:!m.active}).eq('email',id));await refresh();}
    if(action==='generate'){const r=state.records.find(r=>r.id===id);if(r[kind==='material'?'material':'report'])return notify('Hasil tersimpan sudah tampil di kartu ini.');b.textContent='Sedang menyusun…';const {data,error}=await db.functions.invoke('generate-learning',{body:{record_id:id,kind}});if(error){let detail;try{detail=await error.context?.json();}catch{}throw new Error(detail?.error||error.message);}if(data?.error)throw new Error(data.error);await refresh();notify('Hasil AI tersimpan. Periksa isinya sebelum digunakan.');}
  }catch(err){notify(err.message,true);}finally{b.disabled=false;}
});
// Student form: a grade preset fills the starting levels, and the meaning text follows the choice.
document.addEventListener('change',e=>{
  const form=e.target.form;if(form?.dataset.form!=='student'||!form.elements.reading_baseline)return;
  const els=form.elements;const levels=['reading_baseline','math_baseline'];
  if(e.target.name==='phase'&&startPresets[e.target.value])for(const n of levels)if(!els[n].disabled)els[n].value=String(startPresets[e.target.value]);
  for(const n of levels)form.querySelector(`[data-meaning="${n}"]`).textContent=levelMeaning(n.startsWith('math')?'math':'bi',els[n].value);
});
// "＋ Tema lain…" reveals a free-text theme name; any listed theme hides it again.
document.addEventListener('change',e=>{
  if(e.target.name!=='theme'||e.target.form?.dataset.form!=='session')return;
  const custom=e.target.form.querySelector('.theme-custom');const input=custom.querySelector('input');
  custom.hidden=e.target.value!=='__new';input.required=!custom.hidden;if(!custom.hidden)input.focus();
});
// Picking a schedule slot when opening a class pre-selects its children and duration pattern.
document.addEventListener('change',e=>{
  if(e.target.name!=='schedule'||e.target.form?.dataset.form!=='session')return;
  const sc=state.schedules.find(x=>x.id===e.target.value);if(!sc)return;
  const members=scheduleMembers(sc.id);const form=e.target.form;
  form.querySelectorAll('input[name="student"]').forEach(box=>{box.checked=members.has(box.value);});
  form.elements.duration.value=String(durationPattern(minutesBetween(sc.start_time,sc.end_time)));
});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-action]'))e.target.click();});
document.addEventListener('input',e=>{if(e.target.form?.dataset.form==='schedule'&&['start_time','end_time'].includes(e.target.name)){const els=e.target.form.elements;document.querySelector('#schedule-duration').textContent=durationText(els.start_time.value,els.end_time.value);return;}if(e.target.id==='student-search'){state.filter=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#student-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('submit',async e=>{
  e.preventDefault();const form=e.target;const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);
  try{
    guardDemo();const f=new FormData(form);const v=Object.fromEntries(f);const id=form.dataset.id;
    if(form.id==='login-form'){const data=await result(db.auth.signInWithPassword({email:v.email,password:v.password}));await loadUser(data.user);return;}
    switch(form.dataset.form){
      case 'student':{const payload={name:v.name.trim(),parent_name:v.parent_name.trim(),phone:v.phone,interest:v.interest,diagnostic:v.diagnostic,learning_notes:v.learning_notes,reading_target:phaseEnd(v.reading_baseline),math_target:phaseEnd(v.math_baseline)};if(id){const {name,parent_name,phone,interest,diagnostic,learning_notes}=payload;await result(db.rpc('update_student_profile',{p_student:id,p_payload:{name,parent_name,phone,interest,diagnostic,learning_notes,status:v.status}}));const before=state.students.find(x=>x.id===id);if(v.reading_baseline&&(Number(v.reading_baseline)!==before?.reading_baseline||Number(v.math_baseline)!==before?.math_baseline))await result(db.rpc('correct_student_baseline',{p_student:id,p_reading:Number(v.reading_baseline),p_math:Number(v.math_baseline)}));}else{Object.assign(payload,{reading_baseline:Number(v.reading_baseline),math_baseline:Number(v.math_baseline)});await result(db.rpc('create_student',{p_payload:payload}));}break;}
      case 'session':{const ids=f.getAll('student');if(!ids.length)throw new Error('Pilih minimal satu siswa.');const theme=(v.theme&&v.theme!=='__new'?v.theme:v.theme_custom||'').trim();if(!theme)throw new Error('Isi tema bersama.');if(!state.themes.some(t=>t.name===theme))await result(db.from('themes').upsert({name:theme},{onConflict:'name',ignoreDuplicates:true}));const sc=state.schedules.find(x=>x.id===v.schedule);const duration=sc?durationPattern(minutesBetween(sc.start_time,sc.end_time)):Number(v.duration);state.active=await result(db.rpc('create_class',{p_id:id,p_date:v.date,p_theme:theme,p_students:ids,p_duration:duration}));if(sc)await result(db.rpc('set_class_schedule',{p_session:state.active,p_schedule:sc.id}));state.view='sessions';break;}
      case 'schedule':{const mins=minutesBetween(v.start_time,v.end_time);if(!(mins>=30&&mins<=180))throw new Error('Durasi sesi harus 30–180 menit.');const payload={name:v.name.trim(),start_time:v.start_time,end_time:v.end_time};let sid=id;if(sid)await result(db.from('schedules').update(payload).eq('id',sid));else sid=(await result(db.from('schedules').insert(payload).select('id').single())).id;const chosen=f.getAll('student');const old=[...scheduleMembers(sid)];const removed=old.filter(x=>!chosen.includes(x));if(removed.length)await result(db.from('schedule_students').delete().eq('schedule_id',sid).in('student_id',removed));const added=chosen.filter(x=>!old.includes(x));if(added.length)await result(db.from('schedule_students').insert(added.map(student_id=>({schedule_id:sid,student_id}))));break;}
      case 'attendance':await result(db.rpc('save_attendance',{p_id:id,p_attendance:v.attendance}));break;
      case 'evaluation':{const targets=assessmentsFor(id);if(targets.length){const payload=targets.map(a=>({subject:a.subject,rating:v[`rating_${a.subject}`],note:v[`note_${a.subject}`]||''}));const observation={english_rating:v.english_rating||'',english_note:v.english_note||'',character_dimensions:f.getAll('character'),character_note:v.character_note||''};await result(db.rpc('finalize_competency_evaluation',{p_id:id,p_assessments:payload,p_anecdote:v.anecdote||'',p_observation:observation}));}else await result(db.rpc('finalize_evaluation',{p_id:id,p_grade:v.grade||null,p_anecdote:v.anecdote||''}));break;}
      case 'password':{if(v.password!==v.confirm)throw new Error('Kedua kata sandi belum sama.');if(String(v.password).length<8)throw new Error('Kata sandi minimal 8 karakter.');await result(db.auth.updateUser({password:v.password}));document.querySelector('#modal').close();notify('Kata sandi berhasil diganti.');return;}
      case 'summative':await result(db.rpc('complete_summative',{p_student:id,p_score:Number(v.score),p_pass:v.pass==='true'}));break;
      case 'member':await result(db.from('access_list').upsert({email:v.email.trim().toLowerCase(),name:v.name.trim(),role:'teacher',active:true},{onConflict:'email',ignoreDuplicates:true}));break;
      case 'curriculum':{const payload={};for(const subject of subjects){payload[subject]=v[subject];payload[`${subject}_criteria`]=v[`${subject}_criteria`];const lines=String(v[`${subject}_indicators`]||'').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,6);payload[`${subject}_indicators`]=lines;payload[`${subject}_key`]=Math.min(Math.max(0,Number(v[`${subject}_key`])||0),lines.length);payload[`${subject}_spiral`]=String(v[`${subject}_spiral`]||'');}await result(db.from('curriculum').update(payload).eq('level',Number(id)));break;}
    }
    document.querySelector('#modal')?.close();await refresh();notify('Perubahan berhasil disimpan.');
  }catch(err){notify(err.message,true);}finally{buttons.forEach(b=>b.disabled=false);}
});
login();
if(db){db.auth.getSession().then(async({data})=>{if(data.session)try{await loadUser(data.session.user);}catch(err){notify(err.message,true);await db.auth.signOut();resetSession();login();}});db.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){resetSession();login();}});}
